n.edit allowlist (actions/rules/*/*, actions/*, prompts/*, plus a\n13\tfew named files) by construction, the same way engine/simulate.py and\n14\tengine/llm_agents.py already are. The rate constants below live here for\n15\tthe same reason the equations do, not in state/config.json (which the\n16\tnorm-implementer can freely edit) — a fixed formula reading a\n17\tnorm-implementer-editable rate is exactly as rewritable as the formula\n18\titself would be.\n19\t\n20\t`available_stock()` moved in from the old `mechanisms/stock_check.py`\n21\t(2026-09-09, when `mechanisms/` was renamed to `roles/` and reserved for\n22\trole/fluent code only) — it's a trivial one-line accessor, but it's fixed\n23\tprotected infrastructure exactly like everything else here, not\n24\trole-related, so it belongs next to the physics it reads alongside.\n25\t\"\"\"\n26\t\n27\tHARVEST_PRODUCTIVITY = 0.05  # catchability coefficient q in catch_from_effort()\n28\tGROWTH_RATE = 0.2  # logistic growth rate in apply_regrowth()\n29\tCARRYING_CAPACITY_KG = 300  # lake's ceiling, also its starting stock\n30\tCONSUMPTION_KG = 1.0  # fixed per-round cost every fisher owes just to get by\n31\t\n32\t\n33\tdef catch_from_effort(effort, stock_kg):\n34\t    \"\"\"Linear Schaefer-style catch equation (catch = effort x stock x\n35\t    catchability), matching Gupta et al.'s CPRAgent.harvest(). effort is\n36\t    the agent's own [0.0, 1.0] fishing-intensity choice; HARVEST_PRODUCTIVITY\n37\t    is their catchability coefficient q.\"\"\"\n38\t    return effort * stock_kg * HARVEST_PRODUCTIVITY\n39\t\n40\t\n41\tdef apply_regrowth(stock_kg):\n42\t    \"\"\"Logistic growth on the leftover (post-harvest) stock — matches\n43\t    Gupta et al.'s CPRModel.step():\n44\t    ΔR = growth_rate * R * (1 - R/capacity), applied to what's left after\n45\t    harvest, not a flat per-round add. Growth slows as the stock nears\n46\t    carrying capacity and (unlike a flat add) can't outrun a depleted lake.\"\"\"\n47\t    grown = stock_kg + GROWTH_RATE * stock_kg * (1 - stock_kg / CARRYING_CAPACITY_KG)\n48\t    return min(grown, CARRYING_CAPACITY_KG)\n49\t\n50\t\n51\tdef apply_consumption(payoff, harvested_kg):\n52\t    \"\"\"Running per-agent balance: this trip's catch in, the fixed\n53\t    consumption cost out — matches Gupta et al.'s CPRAgent.harvest():\n54\t    self.payoff += harvest_amount; self.payoff -= self.model.consumption.\n55\t    Unlike catch/regrowth this isn't about the lake at all — it's whether\n56\t    a fisher can keep feeding themselves from what they bring in.\"\"\"\n57\t    return payoff + harvested_kg - CONSUMPTION_KG\n58\t\n59\t\n60\tdef is_dead(payoff):\n61\t    \"\"\"Matches Gupta et al.'s `if self.payoff < 0: self.dead = True` —\n62\t    permanent once true; nothing in this project ever resurrects an agent.\"\"\"\n63\t    return payoff < 0\n64\t\n65\t\n66\tdef alive_agent_ids(agents, runtime):\n67\t    \"\"\"The agent_id iteration order every action should use, not\n68\t    state[\"agents\"] directly — excludes anyone in runtime[\"dead_agents\"].\n69\t    One shared helper so death exclusion can't be forgotten by an action\n70\t    rewrite the way a hand-rolled check per action could be.\"\"\"\n71\t    dead = set(runtime.get(\"dead_agents\", []))\n72\t    return [agent_id for agent_id in agents if agent_id not in dead]\n73\t\n74\t\n75\tdef available_stock(runtime):\n76\t    return runtime[\"stock_kg\"]\n```\n\n**`actions/rules/harvest/trip_cap.py`** — TripCapRule(class), after_agent(method)\n\n```python\n1\tfrom engine.institution.rules import Rule\n2\t\n3\tclass TripCapRule(Rule):\n4\t    type_name = \"trip_cap\"\n5\t    description = \"Enforce per-trip catch cap of 15 kg\"\n6\t\n7\t    def after_agent(self, ctx, agent_id, record_entry):\n8\t        cap = self.params.get(\"cap_kg\", 15.0)\n9\t        harvested = record_entry.get(\"harvested_kg\", 0.0)\n10\t        if harvested > cap:\n11\t            # Trim to cap and note violation\n12\t            record_entry[\"harvested_kg\"] = cap\n13\t            note = f\"Trip cap applied: harvested reduced to {cap:.1f} kg.\"\n14\t            # Append note\n15\t            existing = record_entry.get(\"note\") or \"\"\n16\t            record_entry[\"note\"] = (existing + \" \" + note).strip()\n17\t            # Fine 5 kg from ledger\n18\t            ctx.objects.withdraw(\"communal_ledger\", \"balance_kg\", 5.0, by_agent_id=agent_id,\n19\t                narration=f\"Fine for exceeding trip cap applied to {agent_id}.\")\n20\t        return record_entry\n```\n\n**`engine/institution/rules.py`** — Rule(class), __init__(method), before_round(method), after_round(method), before_action(method), +5 more\n\n```python\n24\tfrom engine.institution.registry import discover_subclasses\n25\t\n26\t\n27\tclass Rule:\n28\t    \"\"\"Base class for one entry under actions/rules/{action_name}/. Every\n29\t    hook is optional (all default to a no-op) — implement only the ones a\n30\t    given rule actually needs. `self.key`/`self.params` mirror the old\n31\t    Norm contract exactly (never persist anything on self between hooks;\n32\t    a fresh instance is built every round — use ctx.rule_state(self.key)\n33\t    for anything that must survive across rounds).\"\"\"\n34\t\n35\t    type_name: str = None  # set by every subclass; unique within its own action's rule directory\n36\t\n37\t    def __init__(self, key, params):\n38\t        self.key = key\n39\t        self.params = params\n40\t\n41\t    # --- round-level: fires once per round, independent of any one action ---\n42\t\n43\t    def before_round(self, state, round_number):\n44\t        \"\"\"Once per round, before ANY action in this round's schedule has\n45\t        run. `state` is the full round-state dict (no single ActionContext\n46\t        exists yet at this point — nothing has been resolved to one\n47\t        action's participants).\"\"\"\n48\t        return None\n49\t\n50\t    def after_round(self, state, round_number):\n51\t        \"\"\"