./slurm-6054017.out:1738:{"type":"tool_use","timestamp":1789404663964,"sessionID":"ses_f5f2d2ccdffebj1VCWCVig8v8K","part":{"type":"tool","tool":"read","callID":"call_up3i4lds","state":{"status":"completed","input":{"filePath":"roles/roles.py","limit":2000,"offset":1},"output":"<path>/home/magha601/code/GenerativeSimulation/roles/roles.py</path>\n<type>file</type>\n<content>\n1: def role_holder(role_name, agent_id, fluents, round_number):\n2:     for record in fluents:\n3:         if (\n4:             record[\"fluent\"] == role_name\n5:             and record[\"holder\"] == agent_id\n6:             and record[\"initiated_round\"] <= round_number\n7:             and (record[\"terminated_round\"] is None or record[\"terminated_round\"] > round_number)\n8:         ):\n9:             return record\n10:     return None\n11: \n12: \n13: def current_holder(fluents, role_name, round_number):\n14:     \"\"\"The agent_id currently holding role_name, or None if unassigned.\n15:     Unlike role_holder() above (which checks whether one *specific* agent\n16:     holds a role — the question a fisher's own prompt needs to answer\n17:     about itself), this answers \"who holds it\" without knowing who to ask\n18:     first — the lookup an action needs when its own institution.json\n19:     `actor_role` names a role but the specific agent rotates over rounds.\n20:     Deliberately never cached anywhere (not in institution.json, not on\n21:     any object) — this function, called fresh each time, is the single\n22:     place \"who currently holds this role\" gets answered, so a rotation\n23:     can never leave a second, stale answer sitting somewhere else. Relies\n24:     on the same exclusivity every role fluent already has: one open\n25:     record per role name at a time (set_fact()'s own termination-on-write\n26:     behavior enforces this for role fluents the same as any other).\"\"\"\n27:     for record in fluents:\n28:         if (\n29:             record[\"fluent\"] == role_name\n30:             and record[\"initiated_round\"] <= round_number\n31:             and (record[\"terminated_round\"] is None or record[\"terminated_round\"] > round_number)\n32:         ):\n33:             return record[\"holder\"]\n34:     return None\n35: \n36: \n37: def set_fact(\n38:     fluents, fluent_name, args, holder, round_number,\n39:     narration=None, visibility=\"agent_only\", event_type=\"fact_initiated\",\n40: ):\n41:     \"\"\"General-purpose fluent write: terminate any open record for this\n42:     exact (fluent_name, args) pair, then open a new one. assign_role() is\n43:     the role-shaped special case of this (see below); use this directly for\n44:     non-role facts — an obligation, a sanction, a status a norm wants\n45:     tracked — where `holder` may be an individual agent_id or the sentinel\n46:     \"community\" for a fact that isn't about one specific agent.\n47: \n48:     `narration` is optional, already in-world-phrased plain language\n49:     (the same convention actions/*.py's memory_writes() already uses for its\n50:     `text` field) describing this fact for whoever it's visible to. A\n51:     record with no narration renders nowhere — it's plumbing only (this is\n52:     how plain role_fluent records, like the \"fisher\" role every agent\n53:     holds, stay invisible to the notice renderer without needing a\n54:     migration). `visibility` is `\"public\"` (surfaced to every agent) or\n55:     `\"agent_only\"` (surfaced only when `holder` matches the requesting\n56:     agent) — only meaningful when `narration` is set. Default to\n57:     `\"public\"` for anything a community norm would plausibly want logged or\n58:     monitored (this project's own adopted norms consistently call for\n59:     public ledgers/monitors); use `\"agent_only\"` for something between one\n60:     agent and the mechanism, like an individual warning.\n61: \n62:     Whenever `narration` is set, the same text also reaches the memory\n63:     layer automatically (see `fact_memory_events()` below) — `event_type`\n64:     picks which of `engine/memory/write.py`'s `IMPORTANCE_BY_EVENT_TYPE`\n65:     entries it's logged under; the generic `\"fact_initiated\"` default is\n66:     fine unless a more specific existing type applies (e.g.\n67:     `\"graduated_sanction_applied\"` for a real sanction).\n68:     \"\"\"\n69:     for record in fluents:\n70:         if (\n71:             record[\"fluent\"] == fluent_name\n72:             and record[\"args\"] == args\n73:             and record[\"terminated_round\"] is None\n74:         ):\n75:             record[\"terminated_round\"] = round_number\n76:     record = {\n77:         \"fluent\": fluent_name,\n78:         \"args\": args,\n79:         \"holder\": holder,\n80:         \"initiated_round\": round_number,\n81:         \"terminated_round\": None,\n82:     }\n83:     if narration is not None:\n84:         record[\"narration\"] = narration\n85:         record[\"visibility\"] = visibility\n86:         record[\"event_type\"] = event_type\n87:     fluents.append(record)\n88:     return fluents\n89: \n90: \n91: def end_fact(\n92:     fluents, fluent_name, args, round_number,\n93:     narration=None, visibility=None, event_type=\"fact_ended\",\n94: ):\n95:     \"\"\"Terminate the open record for (fluent_name, args), if any, without\n96:     opening a replacement — e.g. a ban that's been served in full. Pass\n97:     `narration` to describe the closing event itself (e.g. \"Your ban has\n98:     been lifted.\") — same rules as `set_fact()`: reaches prompt (for\n99:     exactly the round it closes, via `visible_facts()`) and memory\n100:     automatically. `visibility` defaults to the record's own opening\n101:     `visibility` if not given; only meaningful when `narration` is set.\"\"\"\n102:     for record in fluents:\n103:         if (\n104:             record[\"fluent\"] == fluent_name\n105:             and record[\"args\"] == args\n106:             and record[\"terminated_round\"] is None\n107:         ):\n108:             record[\"terminated_round\"] = round_number\n109:             if narration is not None:\n110:                 record[\"end_narration\"] = narration\n111:                 record[\"end_visibility\"] = (\n112:                     visibility if visibility is not None else record.get(\"visibility\", \"agent_only\")\n113:                 )\n114:                 record[\"end_event_type\"] = event_type\n115:     return fluents\n116: \n117: \n118: def _visible_to(agent_id, holder, visibility):\n119:     return visibility == \"public\" or holder == agent_id\n120: \n121: \n122: def visible_facts(fluents, agent_id, round_number):\n123:     \"\"\"Every fluent record with something narrated for right now and\n124:     visible to agent_id — either public, or held by agent_id itself. Two\n125:     cases: a currently-holdsAt record's opening `narration` (visible for\n126:     as long as the fact stays open), and a record that closed exactly this\n127:     round, surfaced via its `end_narration` for that one round only (the\n128:     two are mutually exclusive per record: a record can't be both\n129:     currently-open and closed-this-round). Used by the engine's prompt\n130:     renderer to build an agent's \"what's currently true\" section; never\n131:     interprets a raw value itself, only surfaces narration the mechanism\n132:     that wrote the fact already authored.\"\"\"\n133:     results = []\n134:     for record in fluents:\n135:         if (\n136:             record.get(\"narration\")\n137:             and _visible_to(agent_id, record[\"holder\"], record.get(\"visibility\"))\n138:             and record[\"initiated_round\"] <= round_number\n139:             and (record[\"terminated_round\"] is None or record[\"terminated_round\"] > round_number)\n140:         ):\n141:             results.append(record)\n142:         elif (\n143:             record.get(\"terminated_round\") == round_number\n144:             and record.get(\"end_narration\")\n145:             and _visible_to(agent_id, record[\"holder\"], record.get(\"end_visibility\"))\n146:         ):\n147:             results.append({**record, \"narration\": record[\"end_narration\"]})\n148:     return results\n149: \n150: \n151: def fact_memory_events(fluents, round_number):\n152:     \"\"\"Memory-episode specs for every fact newly opened or newly closed\n153:     this exact round that carries narration — pure, no I/O (mirrors the\n154:     shape `actions/*.py`'s `memory_writes()` already returns:\n155:     `{event_type, text, agent_id, group_id}`). The caller\n156:     (`engine/simulate.py`) turns these into actual `write_episode()` calls,\n157:     once per round after all of that round's actions have run — not once\n158:     per action, since a fact set by an early action would otherwise still\n159:     read as \"newly opened\" to a later action's own call and get logged\n160:     twice.\"\"\"\n161:     events = []\n162:     for record in fluents:\n163:         if record.get(\"initiated_round\") == round_number and record.get(\"narration\"):\n164:             events.append(_memory_spec(\n165:                 record[\"holder\"], record.get(\"visibility\", \"agent_only\"),\n166:                 record.get(\"event_type\", \"fact_initiated\"), record[\"narration\"],\n167:             ))\n168:         if record.get(\"terminated_round\") == round_number and record.get(\"end_narration\"):\n169:             events.append(_memory_spec(\n170:                 record[\"holder\"], record.get(\"end_visibility\", \"agent_only\"),\n171:                 record.get(\"end_event_type\", \"fact_ended\"), record[\"end_narration\"],\n172:             ))\n173:     return events\n174: \n175: \n176: def _memory_spec(holder, visibility, event_type, text):\n177:     group_id = \"community\" if visibility == \"public\" else holder\n178:     agent_id = None if holder == \"community\" else holder\n179:     return {\"event_type\": event_type, \"text\": text, \"agent_id\": agent_id, \"group_id\": group_id}\n180: \n181: \n182: def assign_role(\n183:     role_name, agent_id, fluents, round_number, args=None,\n184:     exclusive=False, narration=None, visibility=\"public\", event_type=\"fact_initiated\",\n185: ):\n186:     \"\"\"The default `args=None` (-> `[agent_id]`) is correct only for a role\n187:     every eligible agent holds *simultaneously and independently* (e.g.\n188:     \"fisher\" — one open record per agent, all coexisting on purpose).\n189: \n190:     For a role only one agent holds *at a time* (a rotating recorder,\n191:     steward, monitor), pass `exclusive=True` instead of trying to get\n192:     `args` right yourself — set_fact()'s own termination logic only closes\n193:     a previous record when `(fluent_name, args)` matches exactly, so a\n194:     plain `args=[agent_id]` for an exclusive role means each new holder's\n195:     assignment uses different args than the last, never terminates the\n196:     previous holder's record, and leaves multiple simultaneously-\"open\"\n197:     holders for the same role — confirmed directly: `current_holder()`\n198:     then returns whichever one happens to appear first in `fluents`,\n199:     silently wrong the instant a rotation happens. `exclusive=True` forces\n200:     a fixed `args=[]` regardless of whatever `args` was passed, making\n201:     that mistake structurally unreachable through this parameter rather\n202:     than something the caller has to remember to get right.\n203: \n204:     `narration`/`visibility`/`event_type` let a role grant also be a\n205:     visible, memory-worthy event (e.g. \"Kai has become the pot keeper\") —\n206:     same contract as `set_fact()`, since this is just its role-shaped\n207:     convenience wrapper; previously always silent (`narration=None`).\"\"\"\n208:     resolved_args = [] if exclusive else (args if args is not None else [agent_id])\n209:     return set_fact(\n210:         fluents, role_name, resolved_args, agent_id, round_number,\n211:         narration=narration, visibility=visibility, event_type=event_type,\n212:     )\n\n(End of file - total 212 lines)\n</content>","metadata":{"preview":"def role_holder(role_name, agent_id, fluents, round_number):\n    for record in fluents:\n        if (\n            record[\"fluent\"] == role_name\n            and record[\"holder\"] == agent_id\n            and record[\"initiated_round\"] <= round_number\n            and (record[\"terminated_round\"] is None or record[\"terminated_round\"] > round_number)\n        ):\n            return record\n    return None\n\n\ndef current_holder(fluents, role_name, round_number):\n    \"\"\"The agent_id currently holding role_name, or None if unassigned.\n    Unlike role_holder() above (which checks whether one *specific* agent\n    holds a role — the question a fisher's own prompt needs to answer\n    about itself), this answers \"who holds it\" without knowing who to ask\n    first — the lookup an action needs when its own institution.json\n    `actor_role` names a role but the specific agent rotates over rounds.\n    Deliberately never cached anywhere (not in institution.json, not on","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/magha601/code/GenerativeSimulation/roles/roles.py","text":"def role_holder(role_name, agent_id, fluents, round_number):\n    for record in fluents:\n        if (\n            record[\"fluent\"] == role_name\n            and record[\"holder\"] == agent_id\n            and record[\"initiated_round\"] <= round_number\n            and (record[\"terminated_round\"] is None or record[\"terminated_round\"] > round_number)\n        ):\n            return record\n    return None\n\n\ndef current_holder(fluents, role_name, round_number):\n    \"\"\"The agent_id currently holding role_name, or None if unassigned.\n    Unlike role_holder() above (which checks whether one *specific* agent\n    holds a role — the question a fisher's own prompt needs to answer\n    a